<script setup lang="ts">
const props=defineProps<{summary:any}>()
const emit=defineEmits<{select:[value:string]}>()
const {t,locale}=useI18n()
const table=ref(false)
const number=(n:number)=>Number(n||0).toLocaleString(locale.value)
const total=computed(()=>props.summary.abc_sku_total??Object.values(props.summary.abc||{}).reduce((a:number,b:any)=>a+Number(b),0))
const groups=computed(()=>['A','B','C'].map((label,index)=>({label,color:['#7855FE','#BFB9FE','#EDEFF3'][index],count:props.summary.abc?.[label]||0,quantity:props.summary.abc_outbound?.[label]||0})))
const segments=computed(()=>{let left=0;return groups.value.map(row=>{const width=total.value?100*row.count/total.value:0;const result={...row,left,width};left+=width;return result})})
const curve=computed(()=>(props.summary.abc_curve||[]).map((p:any)=>`${p.sku_share*400},${200-p.outbound_share*200}`).join(' '))
const share=(n:number,d:number)=>d?(100*n/d).toLocaleString(locale.value,{maximumFractionDigits:1})+'%':'—'
</script>
<template><WCard class="abc-report"><header><h2>{{t('inventory-analysis.abc')}} <small>{{t('inventory-analysis.out90')}} {{number(summary.out_qty_90d)}} {{t('inventory-analysis.pieces')}}</small></h2><WButton variant="text" size="sm" @click="table=!table">{{t(table?'inventory-age.chart':'inventory-age.table')}}</WButton></header><p class="help">{{t('inventory-abc.help')}}</p><WEmptyState v-if="!summary.out_qty_90d&&!table" :title="t('inventory-analysis.no-outbound')"/><div v-else-if="!table" class="abc-layout"><div class="chart"><span class="y-title">{{t('inventory-abc.y')}}</span><div class="y-axis"><span v-for="tick in [0,.7,.9,1]" :key="tick" :style="{top:100*(1-tick)+'%'}">{{tick*100}}%</span></div><div class="plot"><button v-for="row in segments" v-show="row.width>0" :key="row.label" class="band" :style="{left:row.left+'%',width:row.width+'%',background:row.color+'40'}" :aria-label="t('inventory-abc.select',{group:row.label})" @click="emit('select',row.label)">{{row.label}}</button><svg viewBox="0 0 400 200" preserveAspectRatio="none" aria-hidden="true"><path d="M0 60H400 M0 20H400" fill="none" stroke="#EDEFF3" vector-effect="non-scaling-stroke"/><polyline :points="curve" fill="none" stroke="#7855FE" stroke-width="2" vector-effect="non-scaling-stroke"/><path d="M0 200H400" stroke="#CDD1DA" vector-effect="non-scaling-stroke"/></svg></div><div class="x-axis"><span v-for="tick in [0,.25,.5,.75,1]" :key="tick" :style="{left:tick*100+'%'}">{{tick*100}}%</span></div><span class="x-title">{{t('inventory-abc.x')}}</span></div><div class="distribution"><div v-for="key in ['count','quantity']" :key="key" class="stack-block"><span>{{t('inventory-abc.'+key)}}</span><div class="stack"><button v-for="row in groups" v-show="row[key as 'count'|'quantity']>0" :key="row.label" :style="{flex:row[key as 'count'|'quantity']+' 1 0px',background:row.color}" :title="row.label+' · '+number(row[key as 'count'|'quantity'])" @click="emit('select',row.label)">{{row.label}}</button><span v-if="key==='count'&&summary.abc_unclassified" :style="{flex:summary.abc_unclassified+' 1 0px'}" :title="t('inventory-abc.unclassified')">—</span></div></div><div class="chips"><button v-for="row in groups" :key="row.label" @click="emit('select',row.label)"><i :style="{background:row.color}"/><span><b>{{row.label}} · {{t('inventory-age.sku-count',{count:number(row.count)})}}</b><small>{{number(row.quantity)}} {{t('inventory-analysis.pieces')}} · {{share(row.quantity,summary.out_qty_90d)}}</small></span></button></div></div></div><div v-else class="table-scroll"><table><thead><tr><th>ABC</th><th>{{t('inventory-abc.count')}}</th><th>{{t('inventory-abc.quantity')}}</th><th>{{t('inventory-age.share')}}</th></tr></thead><tbody><tr v-for="row in groups" :key="row.label"><td><button @click="emit('select',row.label)">{{row.label}}</button></td><td>{{number(row.count)}}</td><td>{{number(row.quantity)}}</td><td>{{share(row.quantity,summary.out_qty_90d)}}</td></tr><tr v-if="summary.abc_unclassified"><td>{{t('inventory-abc.unclassified')}}</td><td>{{number(summary.abc_unclassified)}}</td><td>0</td><td>{{share(0,summary.out_qty_90d)}}</td></tr></tbody></table></div><p v-if="summary.abc_unclassified" class="help">{{t('inventory-abc.unclassified-help',{count:number(summary.abc_unclassified)})}}</p></WCard></template>
<style scoped>
.abc-report :deep(.w-card__body){padding:16px 24px 20px;display:flex;flex-direction:column;gap:12px}header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}h2{font-size:16px;line-height:24px;font-weight:600;margin:0}h2 small{font-size:13px;line-height:20px;font-weight:400;color:var(--w-text-2);margin-left:8px}.help{margin:0;font-size:12px;line-height:18px;color:var(--w-text-3)}.abc-layout{display:flex;flex-wrap:wrap;gap:32px;align-items:flex-start}.chart{flex:1 1 420px;min-width:0;display:grid;grid-template-columns:40px minmax(0,1fr);column-gap:8px;font-size:12px;line-height:18px}.y-title,.x-title{grid-column:2;color:var(--w-text-2);font-weight:500}.y-title{padding-bottom:4px}.x-title{text-align:center;padding-top:4px}.y-axis,.plot{position:relative;height:200px}.y-axis span{position:absolute;right:0;transform:translateY(-50%);color:var(--w-text-3)}.plot svg{position:absolute;inset:0;width:100%;height:200px;pointer-events:none}.band{position:absolute;top:0;bottom:0;border:0;border-left:1px solid var(--w-border-strong);padding:4px 0 0 8px;text-align:left;font:inherit;font-weight:600;color:var(--w-text-1);display:flex;align-items:flex-start;overflow:hidden;cursor:pointer}.x-axis{grid-column:2;position:relative;height:18px;margin-top:4px;color:var(--w-text-3)}.x-axis span{position:absolute;transform:translateX(-50%)}.x-axis span:first-child{transform:none}.x-axis span:last-child{transform:translateX(-100%)}.distribution{flex:1 1 380px;min-width:0;display:flex;flex-direction:column;gap:16px}.stack-block{display:flex;flex-direction:column;gap:6px;font-size:12px;line-height:18px;color:var(--w-text-2)}.stack{display:flex;height:24px;gap:2px}.stack button,.stack>span{min-width:4px;overflow:hidden;border:0;border-radius:2px;font:inherit;font-weight:600;padding:0 8px;color:var(--w-text-1)}.stack button{cursor:pointer}.stack button:first-child{color:white}.stack>span{background:var(--w-line)}.chips{display:flex;flex-wrap:wrap;gap:8px}.chips button{display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--w-border);border-radius:6px;background:var(--w-surface);color:var(--w-text-1);text-align:left;cursor:pointer;font:inherit}.chips i{width:8px;height:8px;border-radius:2px}.chips b{display:block;font-size:13px;line-height:20px;font-weight:600}.chips small{font-size:12px;line-height:18px;color:var(--w-text-3)}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;line-height:20px}th,td{padding:8px;border-bottom:1px solid var(--w-line);text-align:right}th{font-size:12px;color:var(--w-text-3);font-weight:500}th:first-child,td:first-child{text-align:left}td button{border:0;background:none;color:var(--w-link);font:inherit;cursor:pointer;padding:0}
</style>
